793	function cmdUndoEntry(rest: string[]): number {
794	  const flags = parseFlags(rest, ['--request', '--target']);
795	  if (typeof flags === 'string') return usageError(flags);
796	  const requestRaw = oneFlag(flags, '--request');
797	  const targetRaw = oneFlag(flags, '--target');
798	  if (requestRaw === null || targetRaw === null) {
799	    return usageError("'undo' 需要 --request 与 --target 各恰好一个");
800	  }
801	  const requestId = requestRaw.trim();
802	  if (requestId === '') return usageError('撤销请求标识不能为空');
803	  const targetId = targetRaw.trim();
804	  if (targetId === '') return usageError('目标修正请求标识不能为空');
805	  return cmdUndo(requestId, targetId);
806	}
