771	/**
772	 * 执行显式快照救援。调用方已持有目录操作权,快照已通过全部校验。
773	 *
774	 * 阶段:
775	 *  1. 新内容写入 *.rescue-new 临时文件(尚未有任何替换)。
776	 *  2. 记救援日志(preserving)并持久留存:救援前三个业务文件、restore.journal
777	 *     及对应 *.restore-old/*.restore-new 的原始字节与缺失状态写入
778	 *     rescue-preserved-<序号>/(序号取未使用的最小值,重复救援不丢材料、不改写
779	 *     历史)。留存不完整绝不替换。
780	 *  3. committing:整体换入新内容。受控失败先置 rolling-back(此后只能还原
781	 *     救援前状态,不得改向),再幂等回滚。
782	 *  4. 成功:置 done,移除活动位置的旧事务材料与救援日志;留存目录保留。
783	 * 返回留存目录名(供报告)。
784	 */
785	function performRescue(dir: string, files: Array<{ path: string; body: string }>): string {
786	  const journalPath = join(dir, RESCUE_JOURNAL_NAME);
787	  const storeNames = files.map((f) => basename(f.path));
788	
789	  // 阶段一:新内容写入临时文件。此阶段失败不改变任何现有文件。
790	  try {
791	    for (const f of files) {
792	      writeFileSync(f.path + RESCUE_NEW_SUFFIX, f.body, 'utf8');
793	    }
794	  } catch (e) {
795	    for (const f of files) {
796	      try {
797	        if (existsSync(f.path + RESCUE_NEW_SUFFIX)) rmSync(f.path + RESCUE_NEW_SUFFIX);
798	      } catch {
799	        // 清理失败不掩盖原始错误;无救援日志,残留由下次启动清理。
800	      }
801	    }
802	    throw new StoreError(`cannot prepare rescue in ${dir}: ${(e as Error).message}; nothing was changed`);
803	  }
804	
805	  // 阶段二:留存。先记救援日志(preserving 阶段中断等同未开始,启动时退回
806	  // 救援前状态),再把固定名字集的原始字节与缺失状态写入留存目录。
807	  const preserved = preservedNames().map((name) => ({ name, hadOld: existsSync(join(dir, name)) }));
808	  let seq = 1;
809	  let preservedDir = `${PRESERVED_PREFIX}${seq}`;
810	  while (existsSync(join(dir, preservedDir))) {
811	    seq++;
812	    preservedDir = `${PRESERVED_PREFIX}${seq}`;
813	  }
814	  const journal: RescueJournal = { phase: 'preserving', preservedDir, stores: storeNames, preserved };
815	  try {
816	    writeRescueJournalPhase(dir, journal, 'preserving');
817	  } catch (e) {
818	    removeRescueTemps(dir, storeNames);
819	    throw new StoreError(`cannot start rescue in ${dir}: ${(e as Error).message}; nothing was replaced`);
820	  }
821	  try {
822	    mkdirSync(join(dir, preservedDir));
823	    for (const entry of preserved) {
824	      if (entry.hadOld) copyFileSync(join(dir, entry.name), join(dir, preservedDir, entry.name));
825	    }
826	    writeFileSync(
827	      join(dir, preservedDir, RESCUE_MANIFEST_NAME),
828	      JSON.stringify({ format: 'meterwatch-rescue-manifest', version: 1, preserved }, null, 2) + '\n',
829	      'utf8',
830	    );
831	  } catch (e) {
832	    // 留存不完整:绝不替换。业务文件与旧事务材料尚未被改动,尽力清理本次
833	    // 救援自己的临时产物(清理失败由下次启动按 preserving 续接收尾)。
834	    try {
835	      rmSync(journalPath);
836	    } catch {
837	      // 保留救援日志,下次启动按 preserving 退回。
838	    }
839	    removeRescueTemps(dir, storeNames);
840	    try {
841	      rmSync(join(dir, preservedDir), { recursive: true, force: true });
842	    } catch {
843	      // 不完整的留存目录保留,不影响业务状态。
844	    }
845	    throw new StoreError(
846	      `cannot preserve pre-rescue state in ${dir}: ${(e as Error).message}; nothing was replaced`,
847	    );
848	  }
849	
850	  // 阶段三:整体换入新内容。进入 committing 失败时尚未替换任何文件,日志仍
851	  // 为 preserving,下次启动按未开始退回。
852	  try {
853	    writeRescueJournalPhase(dir, journal, 'committing');
854	  } catch (e) {
855	    throw new StoreError(
856	      `rescue could not enter the commit phase: ${(e as Error).message}; ` +
857	        `nothing was replaced; run any meterwatch command again to return to the pre-rescue state`,
858	    );
859	  }
860	  try {
861	    rescueRollForwardPass(dir, journal);
862	  } catch (e) {
863	    // 受控失败:确定回退后不得改向;回滚幂等,可中断续接。
864	    try {
865	      writeRescueJournalPhase(dir, journal, 'rolling-back');
866	    } catch (we) {
867	      throw new StoreError(
868	        `rescue failed (${(e as Error).message}) and the rollback could not be started ` +
869	          `(${(we as Error).message}); data directory ${dir} keeps its rescue materials - ` +
870	          `run any meterwatch command again to continue the rollback`,
871	      );
872	    }
873	    try {
874	      rescueRollbackPass(dir, journal);
875	      rescueRollbackCleanup(dir, journal);
876	    } catch (re) {
877	      throw new StoreError(
878	        `rescue failed (${(e as Error).message}); rollback is in progress and could not finish ` +
879	          `(${(re as Error).message}); data directory ${dir} keeps all materials needed to restore ` +
880	          `the pre-rescue state - run any meterwatch command again to finish it`,
881	      );
882	    }
883	    throw new StoreError(`rescue failed: ${(e as Error).message}; pre-rescue state restored`);
884	  }
885	
886	  // 阶段四:提交已落地,记录完成并收尾。收尾失败不影响快照一致性,下次启动
887	  // 会完成清理。
888	  try {
889	    writeRescueJournalPhase(dir, journal, 'done');
890	    rescueCommitCleanup(dir, journal);
891	  } catch (e) {
892	    throw new StoreError(
893	      `snapshot state was committed but post-rescue cleanup failed: ${(e as Error).message}; ` +
894	        `run any meterwatch command again to finish cleanup`,
895	    );
896	  }
897	  return preservedDir;
898	}
