900	// ---------------------------------------------------------------------------
901	// 启动自恢复(持锁调用)
902	// ---------------------------------------------------------------------------
903	
904	/**
905	 * 续接未完成的恢复。依据日志阶段决定方向:
906	 * - preparing:优先前滚为完整快照;失败再回滚为完整旧库(两方向皆可)。
907	 * - committing:只能前滚;失败不回滚,保留材料并报错,绝不产生混合判定。
908	 * - rolling-back:只能继续还原完整旧库,不能改为前滚。
909	 * - done:完成前滚收尾。
910	 * 成功返回 null;无法可靠判定或完成时返回错误消息,材料一律保留。
911	 */
912	function resumeRestore(dir: string, journal: Journal): string | null {
913	  try {
914	    if (journal.phase === 'preparing') {
915	      rollForwardPass(dir, journal);
916	      writeJournalPhase(dir, journal, 'committing');
917	      rollForwardCleanup(dir, journal);
918	      err('completed an interrupted restore: snapshot state committed');
919	      return null;
920	    }
921	    if (journal.phase === 'committing' || journal.phase === 'done') {
922	      if (journal.phase === 'committing') {
923	        rollForwardPass(dir, journal);
924	        writeJournalPhase(dir, journal, 'done');
925	      }
926	      rollForwardCleanup(dir, journal);
927	      err('completed an interrupted restore: snapshot state committed');
928	      return null;
929	    }
930	    // rolling-back:进入回滚后只能继续还原完整旧库。
931	    rollbackPass(dir, journal);
932	    rollbackCleanup(dir, journal);
933	    err('continued an interrupted rollback: previous state restored');
934	    return null;
935	  } catch (e) {
936	    // preparing 阶段前滚失败时尚未进入失败回滚,可收敛为完整旧库。
937	    if (journal.phase === 'preparing') {
938	      try {
939	        writeJournalPhase(dir, journal, 'rolling-back');
940	        rollbackPass(dir, journal);
941	        rollbackCleanup(dir, journal);
942	        err('rolled back an interrupted restore: previous state restored');
943	        return null;
944	      } catch (re) {
945	        return (
946	          `cannot recover data directory ${dir} to a consistent state: ${(re as Error).message}; ` +
947	          `restore materials were kept in the directory; do not delete ${JOURNAL_NAME} or ` +
948	          `'*${OLD_SUFFIX}'/'*${NEW_SUFFIX}' files, then run any meterwatch command again`
949	        );
950	      }
951	    }
952	    return (
953	      `cannot complete interrupted restore for data directory ${dir}: ${(e as Error).message}; ` +
954	      `restore materials were kept (${JOURNAL_NAME}, '*${OLD_SUFFIX}', '*${NEW_SUFFIX}'); ` +
955	      `resolve the underlying read/write problem and run any meterwatch command again`
956	    );
957	  }
958	}
959	
960	/**
961	 * 任一命令启动时(持锁)调用:若上次救援或恢复被中断,先把数据目录续接为
962	 * 完整快照状态或完整旧状态(救援续接优先,绝不留下或查询混合状态)。没有
963	 * 日志时清理可能残留的临时文件。成功(或无需恢复)返回 null,无法完成返回
964	 * 错误消息。
965	 */
966	function recoverIfNeeded(dir: string): string | null {
967	  // 被中断的救援优先续接:其提交收尾会移除已放弃的旧事务材料,回滚收尾则
968	  // 把旧事务材料(含可能损坏的 restore.journal)还原到位,由下方逻辑继续判定。
969	  const rescueError = continueInterruptedRescue(dir);
970	  if (rescueError !== null) return rescueError;
971	  const journalPath = join(dir, JOURNAL_NAME);
972	  if (existsSync(journalPath)) {
973	    let journal: Journal | null = null;
974	    try {
975	      journal = parseJournal(JSON.parse(readFileSync(journalPath, 'utf8')));
976	    } catch {
977	      journal = null;
978	    }
979	    if (journal === null) {
980	      return (
981	        `cannot recover data directory ${dir}: restore journal ${journalPath} is unreadable or invalid; ` +
982	        `the directory may hold restore materials in an unknown state - nothing was deleted; ` +
983	        `inspect ${JOURNAL_NAME} and '*${OLD_SUFFIX}'/'*${NEW_SUFFIX}' files, or run ` +
984	        `'node app.ts rescue <snapshot>' to explicitly abandon the old transaction and ` +
985	        `restore a known-good snapshot (pre-rescue materials will be preserved)`
986	      );
987	    }
988	    return resumeRestore(dir, journal);
989	  }
990	  // 无日志:提交未开始(残留新临时文件)或已完整完成(残留旧文件备份)。
991	  // 这些残留不属于任何活动事务,清理即可;清理失败明确报错,不继续启动。
992	  for (const path of storeFiles()) {
993	    for (const leftover of [path + NEW_SUFFIX, path + OLD_SUFFIX]) {
994	      if (existsSync(leftover)) {
995	        try {
996	          rmSync(leftover);
997	        } catch (e) {
998	          return `cannot clean up interrupted restore leftover ${leftover}: ${(e as Error).message}`;
999	        }
1000	      }
1001	    }
1002	  }
1003	  // 日志阶段翻转时用的临时名(原子换名前被杀会留下死临时),不影响判定。
1004	  for (const entry of readdirSync(dir)) {
1005	    if (entry.startsWith(`${JOURNAL_NAME}.tmp-`)) {
1006	      try {
1007	        rmSync(join(dir, entry));
1008	      } catch (e) {
1009	        return `cannot clean up interrupted restore leftover ${join(dir, entry)}: ${(e as Error).message}`;
1010	      }
1011	    }
1012	  }
1013	  return null;
1014	}
