472	    let state = readJson(dir, 'alerts.json');
473	    check(S, state.alerts.length === 1 && state.alerts[0].events.length === 1 &&
474	      state.alerts[0].events[0].consumptionMilli === '2000', 'trigger event records 2.000');
475	
476	    // 2) 重复评估(仍超限):保留原标识,不新增事件。
