801	  // 救援日志可能已在上一轮收尾中删除(崩溃发生在删日志与删标记之间);标记
802	  // 才是方向凭据,日志缺失不阻止回退收尾。
803	  rmSync(join(dir, RESCUE_JOURNAL_NAME), { force: true });
804	  clearRescueRollbackMarker(dir);
805	}
806	
807	/**
808	 * 确立回退方向并把救援完整退回救援前状态(持锁调用)。方向以独立标记为准、
809	 * 永久锁定:先确保标记落地,再尽力把救援日志置为 rolling-back(翻转失败不
810	 * 改变方向——标记已在),然后幂等还原全部留存名字并收尾。任一步失败都抛
811	 * 错,材料保留;调用方据此返回 1 并阻止业务。
812	 */
813	function finishRescueRollback(dir: string, journal: RescueJournal, reason: string): never {
814	  // 方向标记在换入前已建立(此处再确保一次,幂等);即使救援日志翻转失败或
815	  // 已被写坏,独立标记仍把方向锁定为回退。
816	  markRescueRollback(dir, journal);
817	  if (journal.phase !== 'rolling-back') {
818	    try {
819	      rescueFaultPoint('rescue-rollback-phase'); // 测试:回退方向日志翻转写失败。
820	      writeRescueJournalPhase(dir, journal, 'rolling-back');
821	    } catch {
822	      // 日志翻转失败不改变已确立的回退方向(独立标记仍在);继续尝试还原。
823	    }
824	  }
825	  // 先幂等还原全部留存名字;任一步受阻都保留材料并阻止业务,绝不报告成功。
826	  try {
827	    rescueRollbackPass(dir, journal);
828	  } catch (e) {
829	    throw new StoreError(
830	      `rescue failed (${reason}); rollback is in progress and could not finish ` +
831	        `(${(e as Error).message}); data directory ${dir} keeps all materials needed to restore ` +
832	        `the pre-rescue state - run any meterwatch command again to finish it; only the rollback can be completed`,
833	    );
834	  }
835	  // 业务文件已还原,仅差删除新临时/救援日志/方向标记:清理失败同样算失败,
836	  // 材料保留,下次启动只能继续完成这次回退。
837	  try {
838	    rescueRollbackCleanup(dir, journal);
839	  } catch (e) {
840	    throw new StoreError(
841	      `rescue failed (${reason}); pre-rescue files were restored but rollback cleanup could not finish ` +
842	        `(${(e as Error).message}); data directory ${dir} keeps its rescue materials - ` +
843	        `run any meterwatch command again to complete the rollback`,
844	    );
845	  }
846	  throw new StoreError(`rescue failed: ${reason}; pre-rescue state restored`);
847	}
848	
849	/**
850	 * 读取并解析回退方向标记;标记不存在返回 undefined,存在但无法作为常规文件
851	 * 读取或结构非法返回 null(无法据此判定)。
852	 */
