 * 读取或结构非法返回 null(无法据此判定)。
 */
function readRollbackMarker(dir: string): RescueJournal | null | undefined {
  const marker = join(dir, RESCUE_ROLLBACK_MARKER);
  if (!existsSync(marker)) return undefined;
